class Solution:
    def maxSum(self, nums: List[int], m: int, l: int, r: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        NEG = float('-inf')
        dp = [NEG] * (n + 1)
        dp[0] = 0
        ans = NEG
        for j in range(1, m + 1):
            ndp = [NEG] * (n + 1)
            for i in range(n + 1):
                ndp[i] = dp[i]
                for t in range(max(0, i - r), i - l + 1):
                    if dp[t] != NEG:
                        ndp[i] = max(ndp[i], dp[t] + P[i] - P[t])
            dp = ndp
            ans = max(ans, max(dp))
        return ans

