from collections import deque
class Solution:
    def maxSum(self, nums: List[int], m: int, l: int, r: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        NEG = float('-inf')
        dp = [NEG] * (n + 1)
        dp[0] = 0
        ans = NEG
        for _ in range(m):
            ndp = [NEG] * (n + 1)
            dq = deque()
            for i in range(n + 1):
                t = i - l
                if t >= 0:
                    v = dp[t] - P[t]
                    while dq and dp[dq[-1]] - P[dq[-1]] <= v:
                        dq.pop()
                    dq.append(t)
                while dq and dq[0] < i - r:
                    dq.popleft()
                ndp[i] = dp[i]
                if dq:
                    ndp[i] = max(ndp[i], P[i] + dp[dq[0]] - P[dq[0]])
            dp = ndp
            ans = max(ans, max(dp))
        return ans

