import java.util.*;
class Solution {
    public long maxSum(int[] nums, int m, int l, int r) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        long NEG = Long.MIN_VALUE / 4;
        long[] dp = new long[n + 1], ndp = new long[n + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        long ans = NEG;
        Deque<Integer> dq = new ArrayDeque<>();
        for (int j = 1; j <= m; j++) {
            Arrays.fill(ndp, NEG);
            dq.clear();
            for (int i = 0; i <= n; i++) {
                int t = i - l;
                if (t >= 0) {
                    long v = dp[t] - P[t];
                    while (!dq.isEmpty() && dp[dq.peekLast()] - P[dq.peekLast()] <= v) dq.pollLast();
                    dq.addLast(t);
                }
                while (!dq.isEmpty() && dq.peekFirst() < i - r) dq.pollFirst();
                ndp[i] = dp[i];
                if (!dq.isEmpty()) ndp[i] = Math.max(ndp[i], P[i] + dp[dq.peekFirst()] - P[dq.peekFirst()]);
            }
            long[] tmp = dp; dp = ndp; ndp = tmp;
            for (long v : dp) ans = Math.max(ans, v);
        }
        return ans;
    }
}

